#include <list>
#include <vector>

int main() {
    std::list<int> myList = {1, 2, 3};

    // Best practice: O(1) guaranteed check across all standard versions
    if (myList.empty()) {
        // Container is empty
    }

    // Although O(1) in C++11+, empty() is preferred idiomatically
    // if (myList.size() == 0) { /* ... */ }

    // Performance implication is negligible for vector/deque, but crucial for list safety
    std::vector<int> myVec;
    bool is_empty = myVec.empty(); 
}
